# Build projects by composing tested components with additional independent cases.
def project(title, description, prereq, source, components, fn, args, body, cases, steps, hints, extension):
    answer='\n'.join(next(x['answer'] for x in items if x['function']==c) for c in components)+'\n'+'def '+fn+'('+args+'):\n'+textwrap.indent(textwrap.dedent(body).strip(),'    ')+'\n'
    projects.append(dict(title=title,description=description,prereq=prereq,sourceKey=source,function=fn,signature=f'{fn}({args})',components=components,answer=answer,cases=[dict(args=a,expected=e) for a,e in cases],steps=steps,hints=hints,extension=extension,code='\n'.join(next(x['starter'] for x in items if x['function']==c) for c in components)+f'\ndef {fn}({args}):\n    # 串联上面的组件，返回最终结果\n    pass\n',expected='通过多个函数行为测试；覆盖正常输入和约定边界。',level='综合实践',minutes=90,provenance='原创分步项目；借鉴公开资源的教学主题，不是高校原作业或教材原题。'))
