def close(a,b):
    if isinstance(b,bool) or b is None or isinstance(b,str): return type(a) is type(b) and a==b
    if isinstance(b,(int,float)): return type(a) in (int,float) and math.isclose(a,b,rel_tol=1e-7,abs_tol=1e-7)
    if isinstance(b,list): return isinstance(a,(list,tuple)) and len(a)==len(b) and all(close(x,y) for x,y in zip(a,b))
    if isinstance(b,dict): return isinstance(a,dict) and a.keys()==b.keys() and all(close(a[k],v) for k,v in b.items())
    return a==b

def extend(exercises, existing_projects, lessons):
    total=0
    for target,records,start in [(exercises,items,len(exercises)),(existing_projects,projects,max(p['id'] for p in existing_projects)+1)]:
        for i,x in enumerate(records,start):
            x['id']=i; x['source']=SOURCES[x['sourceKey']]
            x['example']=dict(x['cases'][0])
            x['constraints']=x.get('constraints','仅使用标准库，输入满足步骤约定；不要修改传入对象。按指定函数接口返回结果，浮点误差容差1e-7。')
            x['walkthrough']=x.get('explanation', '先按步骤完成各个小函数，分别检验后再在主函数中串联。参考实现复用了练习组件，每个步骤都能对应到一段代码。')
            if 'lesson' in x:
                l=lessons[x['lesson']];x.update(module=l['module'],category=l['category'])
            with tempfile.TemporaryDirectory() as tmp:
                scope={};exec(x['answer'],scope)
                for n,c in enumerate(x['cases']):
                    args=json.loads(json.dumps(c['args']));before=json.dumps(args,sort_keys=True)
                    actual=scope[x['function']](*args)
                    assert close(actual,c['expected']),(x['title'],n,actual,c['expected'])
                    assert json.dumps(args,sort_keys=True)==before,('input mutated',x['title'])
                    total+=1
            target.append(x)
    report=dict(new_exercises=len(items),new_projects=len(projects),behavior_cases=total,sources=list(SOURCES.values()),updated='2026-10-22')
    (ROOT/'curriculum/practice-counts.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
    (ROOT/'dist/practice-sources.json').write_text(json.dumps(SOURCES,ensure_ascii=False,indent=2))
    return report
